package com.novacommerce.order.config; import java.time.Clock; import org.springframework.boot.context.properties.EnableConfigurationProperties; import org.springframework.context.annotation.*; import org.springframework.web.client.RestClient;
@Configuration @EnableConfigurationProperties(OrderProperties.class) public class OrderConfiguration {@Bean Clock orderClock(){return Clock.systemUTC();}@Bean("catalogRestClient")RestClient catalog(RestClient.Builder b,OrderProperties p){return b.baseUrl(p.getCatalogBaseUrl()).build();}@Bean("inventoryRestClient")RestClient inventory(RestClient.Builder b,OrderProperties p){return b.baseUrl(p.getInventoryBaseUrl()).build();}}
